                let ts_str: String = row.get(2)?;
                let updated_at = DateTime::parse_from_rfc3339(&ts_str)
                    .map(|dt| dt.with_timezone(&Utc))
                    .unwrap_or_else(|_| Utc::now());
                Ok(RepoSession {
                    session_id: row.get(0)?,
                    session_name: row.get(1)?,
                    updated_at,
                    branch: String::new(),
                    agent: row.get(3)?,
                    backed_up: true,
                })
