use anyhow::Result;
use chrono::{DateTime, Local, Utc};
use crossterm::{
    cursor,
    event::{self, Event, KeyCode},
    execute,
    terminal::{self, ClearType, EnterAlternateScreen, LeaveAlternateScreen},
};
use std::collections::HashSet;
use std::env;
use std::io::{self, BufRead, Write};
use std::path::PathBuf;

use crate::{db, entity::session::Session, commands::status::fetch_repos};

struct DisplaySession {
    session_id: String,
    session_name: String,
    cwd: String,
    branch: String,
    updated_at: DateTime<Utc>,
    agent_name: String,
    backed_up: bool,
}

enum Action {
    Show(String),
    Resume(String, String), // (id, cwd)
}

pub fn run(all: bool, json: bool) -> Result<()> {
    let conn = db::connect()?;

    let repos = fetch_repos(&conn)?;
    let cwd_env = env::current_dir().ok().map(|p| p.to_string_lossy().to_string());
    let current_repo: Option<&crate::entity::repository::Repository> = cwd_env.as_deref()
        .and_then(|cwd| repos.iter().find(|r| cwd.starts_with(r.directory.as_str())));
    let current_repo_id: Option<i64> = current_repo.map(|r| r.id as i64);

    // Pull branch + repo_id alongside the existing columns. They're nullable
    // because older rows predate the index pass that populates them.
    let mut stmt = conn.prepare(
        "SELECT session_id, agent_name, user, created_at, updated_at, cwd, session_name,
                tokens_used, COALESCE(branch, ''), repo_id
         FROM sessions ORDER BY updated_at DESC"
    )?;

    let db_rows: Vec<(Session, String, Option<i64>)> = stmt.query_map([], |row| {
        let created_str: String = row.get(3)?;
        let updated_str: String = row.get(4)?;
        let session = Session {
            session_id: row.get(0)?,
            agent_name: row.get(1)?,
            user: row.get(2)?,
            created_at: DateTime::parse_from_rfc3339(&created_str)
                .map(|dt| dt.with_timezone(&Utc))
                .unwrap_or_else(|_| Utc::now()),
            updated_at: DateTime::parse_from_rfc3339(&updated_str)
                .map(|dt| dt.with_timezone(&Utc))
                .unwrap_or_else(|_| Utc::now()),
            cwd: row.get(5)?,
            session_name: row.get(6)?,
            tokens_used: row.get(7)?,
        };
        let branch: String = row.get(8)?;
        let repo_id: Option<i64> = row.get(9)?;
        Ok((session, branch, repo_id))
    })?
    .collect::<Result<Vec<_>, _>>()?;

    let known_ids: HashSet<String> = db_rows.iter().map(|(s, _, _)| s.session_id.clone()).collect();
    let cutoff = Utc::now() - chrono::Duration::days(3);

    // Track repo_id alongside the displayed session so the sort below can
    // identify same-repo sessions across different users' clone paths.
    let mut sessions_with_repo: Vec<(DisplaySession, Option<i64>)> = db_rows.into_iter()
        .filter(|(s, _, _)| all || s.updated_at >= cutoff)
        .map(|(s, branch, repo_id)| (DisplaySession {
            session_id: s.session_id,
            session_name: s.session_name,
            cwd: s.cwd,
            branch,
            updated_at: s.updated_at,
            agent_name: s.agent_name,
            backed_up: true,
        }, repo_id))
        .collect();

    // Live JSONLs in ~/.claude/projects: always local to the current user, so
    // tag them with the current repo_id (if any) for the sort.
    for live in scan_claude_projects(&known_ids, all, cutoff) {
        sessions_with_repo.push((live, current_repo_id));
    }

    // Sessions for the current repo first (matched by repo_id, not cwd path),
    // then by recency. This is how Scott's sessions on the same repo end up
    // interleaved with yours instead of pinned to the bottom.
    sessions_with_repo.sort_by(|a, b| {
        let a_local = current_repo_id.is_some() && a.1 == current_repo_id;
        let b_local = current_repo_id.is_some() && b.1 == current_repo_id;
        b_local.cmp(&a_local).then(b.0.updated_at.cmp(&a.0.updated_at))
    });

    let sessions: Vec<DisplaySession> = sessions_with_repo.into_iter()
        .map(|(s, _)| s).collect();

    if json {
        let arr: Vec<serde_json::Value> = sessions.iter().map(|s| serde_json::json!({
            "session_id": s.session_id,
            "session_name": s.session_name,
            "cwd": s.cwd,
            "branch": s.branch,
            "agent": s.agent_name,
            "updated_at": s.updated_at.to_rfc3339(),
            "backed_up": s.backed_up,
        })).collect();
        println!("{}", serde_json::to_string_pretty(&serde_json::json!({ "sessions": arr }))?);
        return Ok(());
    }

    if sessions.is_empty() {
        println!("No sessions found.");
        return Ok(());
    }

