423	#[allow(clippy::type_complexity)]
424	pub(crate) fn parse_session(
425	    meta_bytes: &[u8],
426	    jsonl_bytes: &[u8],
427	    user: &str,
428	) -> Result<(String, String, String, String, String, String, String)> {
429	    #[derive(Deserialize)]
430	    struct SessionMetadata {
431	        session_id: String,
432	        agent: Option<String>,
433	        created_at: Option<String>,
434	        branch: Option<String>,
435	        summary: Option<Summary>,
436	    }
437	    #[derive(Deserialize)]
438	    struct Summary {
439	        intent: Option<String>,
440	    }
441	
442	    let _ = user; // signature kept for callers; user comes from env at upsert time
443	
444	    let meta: SessionMetadata = serde_json::from_slice(meta_bytes)
445	        .context("failed to parse metadata.json")?;
446	
447	    let created_at: DateTime<Utc> = meta
448	        .created_at
449	        .as_deref()
450	        .and_then(|s| DateTime::parse_from_rfc3339(s).ok())
451	        .map(|dt| dt.with_timezone(&Utc))
452	        .unwrap_or_else(Utc::now);
453	
454	    let session_name = meta
455	        .summary
456	        .and_then(|s| s.intent)
457	        .filter(|s| !s.is_empty())
458	        .unwrap_or_else(|| format!("session:{}", &meta.session_id[..8]));
459	
460	    let agent_name = meta.agent.unwrap_or_else(|| "unknown".to_string());
461	    let meta_branch = meta.branch.unwrap_or_default();
462	
463	    let mut latest: Option<DateTime<Utc>> = None;
464	    let mut cwd = String::new();
465	    let mut last_prompt: Option<String> = None;
466	    let mut custom_title: Option<String> = None;
467	    let mut jsonl_branch = String::new();
468	
469	    for line in jsonl_bytes.split(|&b| b == b'\n') {
470	        if line.is_empty() { continue; }
471	        let v: Value = match serde_json::from_slice(line) {
472	            Ok(v) => v,
473	            Err(_) => continue,
474	        };
475	
476	        if let Some(ts) = v.get("timestamp").and_then(Value::as_str) {
477	            if let Ok(dt) = DateTime::parse_from_rfc3339(ts) {
478	                let dt: DateTime<Utc> = dt.with_timezone(&Utc);
479	                if latest.map_or(true, |l| dt > l) { latest = Some(dt); }
480	            }
481	        }
482	
483	        if cwd.is_empty() {
484	            if let Some(c) = v.get("cwd").and_then(Value::as_str) { cwd = c.to_string(); }
485	        }
486	
487	        if let Some(b) = v.get("gitBranch").and_then(Value::as_str) {
488	            if !b.is_empty() { jsonl_branch = b.to_string(); }
489	        }
490	
491	        match v.get("type").and_then(Value::as_str) {
492	            Some("custom-title") => {
493	                if let Some(t) = v.get("customTitle").and_then(Value::as_str) {
494	                    if !t.trim().is_empty() { custom_title = Some(t.trim().to_string()); }
495	                }
496	            }
