fn build_groups(hits: Vec<SearchHit>) -> Vec<Group> {
    let mut groups: Vec<Group> = Vec::new();
    let mut log_group_idx: std::collections::HashMap<String, usize> = std::collections::HashMap::new();

    for hit in hits {
        match hit.kind {
            HitKind::Log => {
                let sid = hit.session_id.clone().unwrap_or_default();
                if let Some(&gi) = log_group_idx.get(&sid) {
                    groups[gi].rows.push(GroupRow {
                        hit_ts: hit.hit_ts,
                        start_ts: hit.start_ts,
                        lines: hit.excerpt_lines,
                    });
                } else {
                    let gi = groups.len();
                    if !sid.is_empty() { log_group_idx.insert(sid, gi); }
                    groups.push(Group {
                        title: hit.title,
                        dir: hit.dir,
                        branch: hit.branch,
                        agent: hit.agent,
                        backed_up: hit.backed_up,
                        updated_at: hit.updated_at,
                        remote: hit.remote,
                        session_id: hit.session_id,
                        repo_dir: None,
                        kind: HitKind::Log,
                        rows: vec![GroupRow {
                            hit_ts: hit.hit_ts,
                            start_ts: hit.start_ts,
                            lines: hit.excerpt_lines,
                        }],
                    });
                }
            }
            HitKind::Session => {
                groups.push(Group {
                    title: hit.title,
                    dir: hit.dir,
                    branch: String::new(),
                    agent: hit.agent,
                    backed_up: hit.backed_up,
                    updated_at: hit.updated_at,
                    remote: hit.remote,
                    session_id: hit.session_id,
                    repo_dir: None,
                    kind: HitKind::Session,
                    rows: vec![],
                });
            }
            HitKind::Repo => {
                groups.push(Group {
                    title: hit.title,
                    dir: hit.dir,
                    branch: String::new(),
                    agent: String::new(),
                    backed_up: false,
                    updated_at: String::new(),
                    remote: hit.remote,
                    session_id: None,
                    repo_dir: hit.repo_dir,
                    kind: HitKind::Repo,
                    rows: vec![],
                });
            }
        }
    }

    groups
}

