~/.cargo/bin/gossamer search "the" -n 30 --json 2>&1 | /opt/homebrew/bin/python3 -c "
import json, sys
data = json.load(sys.stdin)
def djb2(s):
    h = 5381
    for b in s.encode():
        h = (h * 33 + b) & 0xffffffff
    return h
PALETTE = [141, 113, 209, 110, 173, 219, 156, 180]
seen = {}
for r in data['results']:
    a = r.get('author', '')
    if a and a not in seen:
        seen[a] = PALETTE[djb2(a) % len(PALETTE)]
for a, c in seen.items():
    print(f'  \\x1b[38;5;{c}m{a}\\x1b[0m  → 256-color={c}')
"

