            author_name  = excluded.author_name,
            author_email = excluded.author_email,
            last_turn_ts = excluded.last_turn_ts,
            jsonl_path   = excluded.jsonl_path,
            repo_dir     = excluded.repo_dir,
            os_user      = excluded.os_user",
