//! Codex JSONL pipeline. STUB — only reads `metadata.json` today.
//!
//! Codex's `full.jsonl` is structurally different from Claude Code:
//! every entry is `{"type": "session_meta"|"response_item"|"event_msg"|...,
//! "payload": {...}}` with user/assistant turns nested as
//! `response_item.payload.message.content[*].{input_text,output_text}`.
//!
//! For now this parser only consumes metadata.json fields. Until the JSONL
//! adapter lands, Codex sessions get:
//!   - session_id, agent, created_at, branch from metadata.json
//!   - cwd: best-effort from `session_meta`'s first entry in full.jsonl
//!   - session_name: falls back to `session:<short_id>` (no first-prompt
//!     extraction yet)
//!   - name_is_explicit: false
//!
//! Adding real JSONL parsing here is the follow-up. Keep the surface area of
//! ParsedSession identical to claude_code so the dispatch is transparent.

use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use serde::Deserialize;
use serde_json::Value;

use super::ParsedSession;

pub fn parse_session(meta_bytes: &[u8], jsonl_bytes: &[u8]) -> Result<ParsedSession> {
    #[derive(Deserialize)]
    struct SessionMetadata {
        session_id: String,
        agent: Option<String>,
        created_at: Option<String>,
        branch: Option<String>,
    }

    let meta: SessionMetadata = serde_json::from_slice(meta_bytes)
        .context("failed to parse metadata.json")?;

    let created_at: DateTime<Utc> = meta
        .created_at
        .as_deref()
        .and_then(|s| DateTime::parse_from_rfc3339(s).ok())
        .map(|dt| dt.with_timezone(&Utc))
        .unwrap_or_else(Utc::now);

    let agent_name = meta.agent.unwrap_or_else(|| "Codex".to_string());
    let branch = meta.branch.unwrap_or_default();

    // Best-effort cwd + updated_at from the JSONL. Codex puts cwd inside the
    // first `session_meta` entry's payload. Real session_name / first-prompt
    // extraction will land here when the JSONL adapter is written.
    let (cwd, updated_at) = scan_minimal(jsonl_bytes, created_at);

    let session_name = format!("session:{}", &meta.session_id[..meta.session_id.len().min(8)]);
    let session_name = crate::commands::session_list::sanitize_one_line(&session_name);

    Ok(ParsedSession {
        session_id: meta.session_id,
        agent_name,
        created_at: created_at.to_rfc3339(),
        updated_at: updated_at.to_rfc3339(),
        cwd,
        session_name,
        branch,
        name_is_explicit: false,
    })
}

/// Walk the JSONL just enough to grab cwd (from session_meta) and the latest
/// timestamp. Cheap; full content parsing waits for the real adapter.
fn scan_minimal(jsonl_bytes: &[u8], fallback: DateTime<Utc>) -> (String, DateTime<Utc>) {
    let mut cwd = String::new();
    let mut latest: Option<DateTime<Utc>> = None;

    for line in jsonl_bytes.split(|&b| b == b'\n') {
        if line.is_empty() { continue; }
        let v: Value = match serde_json::from_slice(line) {
            Ok(v) => v,
            Err(_) => continue,
        };

        if let Some(ts) = v.get("timestamp").and_then(Value::as_str) {
            if let Ok(dt) = DateTime::parse_from_rfc3339(ts) {
                let dt: DateTime<Utc> = dt.with_timezone(&Utc);
                if latest.map_or(true, |l| dt > l) { latest = Some(dt); }
            }
        }

        if cwd.is_empty() && v.get("type").and_then(Value::as_str) == Some("session_meta") {
            if let Some(c) = v["payload"]["cwd"].as_str() {
                cwd = c.to_string();
            }
        }
    }

    (cwd, latest.unwrap_or(fallback))
}

