use anyhow::Result;
use std::process::Command;

use crate::db;
use super::index::{
    BRANCH, fetch_checkpoint_branch, git_show, index_shadow_branches, is_meta_path,
    upsert_session,
};

pub fn run(json: bool) -> Result<()> {
    let conn = db::connect()?;

    let mut stmt = conn.prepare("SELECT id, directory, name FROM repositories")?;
    let repos: Vec<(i64, String, String)> = stmt
        .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
        .collect::<Result<_, _>>()?;

    if repos.is_empty() {
        if json {
            println!("{}", serde_json::json!({"sessions_indexed": 0}));
        } else {
            println!("No repositories tracked. Run `gossamer init` first.");
        }
        return Ok(());
    }

    let mut grand_total = 0usize;

    for (repo_id, dir, name) in &repos {
        match refresh_repo(&conn, *repo_id, dir) {
            Ok(0) => { if !json { println!("'{}': up to date.", name); } }
            Ok(n) => {
                if !json { println!("'{}': {} new session(s) indexed.", name, n); }
                grand_total += n;
            }
            Err(e) => eprintln!("'{}': error — {}", name, e),
        }
    }

    let names_filled = crate::ingest::backfill_session_names().unwrap_or(0);

    if json {
        println!("{}", serde_json::to_string_pretty(&serde_json::json!({
            "sessions_indexed": grand_total,
            "names_backfilled": names_filled,
        }))?);
    } else {
        println!();
        if grand_total > 0 {
            println!("{} new session(s) indexed.", grand_total);
        } else {
            println!("All repositories up to date.");
        }
        if names_filled > 0 {
            println!("{} session name(s) backfilled.", names_filled);
        }
    }

    Ok(())
}

fn refresh_repo(conn: &rusqlite::Connection, repo_id: i64, repo_dir: &str) -> Result<usize> {
    fetch_checkpoint_branch(repo_dir);

    // Shadow branches advance on every prompt, so we always sweep them — even
    // when the checkpoint head is unchanged, an active session can have new
    // turns visible only on its shadow ref.
    let shadow_count = index_shadow_branches(conn, repo_id, repo_dir).unwrap_or(0);

    // Check checkpoint branch exists.
    let check = Command::new("git")
        .args(["rev-parse", "--verify", BRANCH])
        .current_dir(repo_dir)
        .output()?;

    if !check.status.success() {
        return Ok(shadow_count);
    }

    let current_head = String::from_utf8(check.stdout)?.trim().to_string();

    // Load stored watermark.
    let stored_head: Option<String> = conn.query_row(
        "SELECT last_indexed_commit FROM repositories WHERE directory = ?1",
        [repo_dir],
        |row| row.get(0),
    ).ok().flatten();

    if stored_head.as_deref() == Some(current_head.as_str()) {
        return Ok(shadow_count); // checkpoint unchanged; shadow may still have new turns
    }

    // Collect metadata paths: added or modified since watermark (or all if first run).
    let meta_paths: Vec<String> = if let Some(ref last) = stored_head {
        // git diff gives a deduplicated file list between two tree states, so each
        // session appears at most once even if it was checkpointed many times.
        let out = Command::new("git")
            .args(["diff", "--name-only", "--diff-filter=AM", last, BRANCH])
            .current_dir(repo_dir)
            .output()?;
        String::from_utf8(out.stdout)?
            .lines()
            .filter(|l| is_meta_path(l))
            .map(str::to_string)
            .collect()
    } else {
        let out = Command::new("git")
            .args(["ls-tree", "-r", "--name-only", BRANCH])
            .current_dir(repo_dir)
            .output()?;
        String::from_utf8(out.stdout)?
            .lines()
            .filter(|l| is_meta_path(l))
            .map(str::to_string)
            .collect()
    };

    let user = std::env::var("USER")
        .or_else(|_| std::env::var("USERNAME"))
        .unwrap_or_else(|_| "unknown".to_string());

    let mut count = 0;
    for meta_path in &meta_paths {
        let jsonl_path = format!(
            "{}full.jsonl",
            &meta_path[..meta_path.len() - "metadata.json".len()]
        );
        let meta_bytes = match git_show(repo_dir, meta_path) {
            Ok(b) => b,
            Err(e) => { eprintln!("  skipping {}: {}", meta_path, e); continue; }
        };
        let jsonl_bytes = match git_show(repo_dir, &jsonl_path) {
            Ok(b) => b,
            Err(_) => continue,
        };
        match crate::parsers::dispatch_session(&meta_bytes, &jsonl_bytes) {
            Ok(p) => {
                upsert_session(conn, &p.session_id, &p.agent_name, &user,
                               &p.created_at, &p.updated_at, &p.cwd, &p.session_name,
                               &p.branch, Some(repo_id), p.name_is_explicit)?;
                count += 1;
            }
            Err(e) => eprintln!("  skipping {}: {}", meta_path, e),
        }
    }

    // Advance watermark.
    conn.execute(
        "UPDATE repositories SET last_indexed_commit = ?1 WHERE directory = ?2",
        rusqlite::params![current_head, repo_dir],
    )?;

    Ok(count + shadow_count)
}

//! Claude Code JSONL pipeline. Each line is a top-level
//! `{"type": "user"|"assistant"|"system"|"custom-title", ...}` event.
//! User/assistant turns carry their content in `message.content`, which can
//! be either a plain string or an array of `{"type": "text"|"tool_use"|..., ...}`
//! blocks. cwd and gitBranch are stamped onto each user/system entry.

use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use serde::Deserialize;
use serde_json::Value;

use super::ParsedSession;

pub fn parse_session(meta_bytes: &[u8], jsonl_bytes: &[u8]) -> Result<ParsedSession> {
    #[derive(Deserialize)]
    struct SessionMetadata {
        session_id: String,
        agent: Option<String>,
        created_at: Option<String>,
        branch: Option<String>,
        summary: Option<Summary>,
    }
    #[derive(Deserialize)]
    struct Summary {
        intent: Option<String>,
    }

    let meta: SessionMetadata = serde_json::from_slice(meta_bytes)
        .context("failed to parse metadata.json")?;

    let created_at: DateTime<Utc> = meta
        .created_at
        .as_deref()
        .and_then(|s| DateTime::parse_from_rfc3339(s).ok())
        .map(|dt| dt.with_timezone(&Utc))
        .unwrap_or_else(Utc::now);

    let metadata_intent = meta
        .summary
        .and_then(|s| s.intent)
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| format!("session:{}", &meta.session_id[..8]));

    let agent_name = meta.agent.unwrap_or_else(|| "Claude Code".to_string());
    let meta_branch = meta.branch.unwrap_or_default();

    let mut latest: Option<DateTime<Utc>> = None;
    let mut cwd = String::new();
    let mut first_meaningful_prompt: Option<String> = None;
    let mut first_any_prompt: Option<String> = None;
    let mut custom_title: Option<String> = None;
    let mut jsonl_branch = String::new();

    for line in jsonl_bytes.split(|&b| b == b'\n') {
        if line.is_empty() { continue; }
        let v: Value = match serde_json::from_slice(line) {
            Ok(v) => v,
            Err(_) => continue,
        };

        if let Some(ts) = v.get("timestamp").and_then(Value::as_str) {
            if let Ok(dt) = DateTime::parse_from_rfc3339(ts) {
                let dt: DateTime<Utc> = dt.with_timezone(&Utc);
                if latest.map_or(true, |l| dt > l) { latest = Some(dt); }
            }
        }

        if cwd.is_empty() {
            if let Some(c) = v.get("cwd").and_then(Value::as_str) { cwd = c.to_string(); }
        }

        if let Some(b) = v.get("gitBranch").and_then(Value::as_str) {
            if !b.is_empty() { jsonl_branch = b.to_string(); }
        }

        match v.get("type").and_then(Value::as_str) {
            Some("custom-title") => {
                if let Some(t) = v.get("customTitle").and_then(Value::as_str) {
                    if !t.trim().is_empty() { custom_title = Some(t.trim().to_string()); }
                }
            }
            Some("user") => {
                if let Some(text) = extract_user_text(&v["message"]["content"]) {
                    if first_any_prompt.is_none() { first_any_prompt = Some(text.clone()); }
                    if first_meaningful_prompt.is_none() && !is_wrapper_prompt(&text) {
                        first_meaningful_prompt = Some(text);
                    }
                }
            }
            _ => {}
        }
    }

    let updated_at = latest.unwrap_or(created_at);
    let name_is_explicit = custom_title.is_some();
    let session_name = custom_title
        .or(first_meaningful_prompt)
        .or(first_any_prompt)
        .unwrap_or(metadata_intent);
    let session_name = crate::commands::session_list::sanitize_one_line(&session_name);
    let branch = if !jsonl_branch.is_empty() { jsonl_branch } else { meta_branch };

    Ok(ParsedSession {
        session_id: meta.session_id,
        agent_name,
        created_at: created_at.to_rfc3339(),
        updated_at: updated_at.to_rfc3339(),
        cwd,
        session_name,
        branch,
        name_is_explicit,
    })
}

pub fn parse_shadow_session(jsonl_bytes: &[u8], session_id: &str) -> Result<ParsedSession> {
    let mut earliest: Option<DateTime<Utc>> = None;
    let mut latest: Option<DateTime<Utc>> = None;
    let mut cwd = String::new();
    let mut first_meaningful_prompt: Option<String> = None;
    let mut first_any_prompt: Option<String> = None;
    let mut custom_title: Option<String> = None;
    let mut branch = String::new();

    for line in jsonl_bytes.split(|&b| b == b'\n') {
        if line.is_empty() { continue; }
        let v: Value = match serde_json::from_slice(line) {
            Ok(v) => v,
            Err(_) => continue,
        };

        if let Some(ts) = v.get("timestamp").and_then(Value::as_str) {
            if let Ok(dt) = DateTime::parse_from_rfc3339(ts) {
                let dt: DateTime<Utc> = dt.with_timezone(&Utc);
                if earliest.map_or(true, |e| dt < e) { earliest = Some(dt); }
                if latest.map_or(true, |l| dt > l)   { latest   = Some(dt); }
            }
        }

        if cwd.is_empty() {
            if let Some(c) = v.get("cwd").and_then(Value::as_str) { cwd = c.to_string(); }
        }

        if let Some(b) = v.get("gitBranch").and_then(Value::as_str) {
            if !b.is_empty() { branch = b.to_string(); }
        }

        match v.get("type").and_then(Value::as_str) {
            Some("custom-title") => {
                if let Some(t) = v.get("customTitle").and_then(Value::as_str) {
                    if !t.trim().is_empty() { custom_title = Some(t.trim().to_string()); }
                }
            }
            Some("user") => {
                if let Some(text) = extract_user_text(&v["message"]["content"]) {
                    if first_any_prompt.is_none() { first_any_prompt = Some(text.clone()); }
                    if first_meaningful_prompt.is_none() && !is_wrapper_prompt(&text) {
                        first_meaningful_prompt = Some(text);
                    }
                }
            }
            _ => {}
        }
    }

    let created_at = earliest.unwrap_or_else(Utc::now);
    let updated_at = latest.unwrap_or(created_at);
    let name_is_explicit = custom_title.is_some();
    let session_name = custom_title
        .or(first_meaningful_prompt)
        .or(first_any_prompt)
        .unwrap_or_else(|| format!("session:{}", &session_id[..session_id.len().min(8)]));
    let session_name = crate::commands::session_list::sanitize_one_line(&session_name);

    Ok(ParsedSession {
        session_id: session_id.to_string(),
        agent_name: "Claude Code".to_string(),
        created_at: created_at.to_rfc3339(),
        updated_at: updated_at.to_rfc3339(),
        cwd,
        session_name,
        branch,
        name_is_explicit,
    })
}

/// Pull a user message's text out of either the string or block-array shape
/// that Claude Code uses. Trims and returns None for empty content.
fn extract_user_text(content: &Value) -> Option<String> {
    match content {
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() { None } else { Some(t.to_string()) }
        }
        Value::Array(blocks) => {
            let texts: Vec<&str> = blocks.iter()
                .filter(|b| b.get("type").and_then(Value::as_str) == Some("text"))
                .filter_map(|b| b.get("text").and_then(Value::as_str))
                .collect();
            let joined = texts.join("\n");
            let t = joined.trim();
            if t.is_empty() { None } else { Some(t.to_string()) }
        }
        _ => None,
    }
}

/// Prompts whose first line is just a wrapper tag carry no user intent —
/// they're slash-command metadata, bash output captured by Claude Code, task
/// notifications, etc. Skip these when deciding the session's display name.
fn is_wrapper_prompt(text: &str) -> bool {
    let first_line = text.lines().next().unwrap_or("").trim_start();
    const TAGS: &[&str] = &[
        "<command-message",
        "<command-name",
        "<local-command-caveat",
        "<local-command-stdout",
        "<local-command-stderr",
        "<task-notification",
        "<system-reminder",
        "<bash-input",
        "<bash-stdout",
        "<bash-stderr",
    ];
    TAGS.iter().any(|tag| first_line.starts_with(tag))
}

use anyhow::Result;
use clap::{Parser, Subcommand};

mod commands;
mod config;
mod db;
mod entity;
mod ingest;
mod parsers;
mod theme;
mod watermark;

#[derive(Parser)]
#[command(name = "gossamer", about = "Manage AI sessions with entireio")]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    /// Output as JSON instead of an interactive TUI
    #[arg(long, global = true)]
    json: bool,
}

#[derive(Subcommand)]
enum Commands {
    /// Initialize gossamer in the current git repository
    Init,
    /// Print all repositories tracked by gossamer
    Repo,
    /// Print sessions from the past 3 days
    Sessions {
        /// Show all sessions regardless of age
        #[arg(long)]
        all: bool,
    },
    /// Scan checkpoint logs and index sessions into the database
    Index,
    /// Incrementally index only new checkpoint commits since the last index/refresh
    Refresh,
    /// Browse a session's messages interactively (arrow keys to navigate)
    Show {
        /// Session ID or path to a JSONL file
        session: String,
    },
    /// Semantic search across indexed sessions
    Search {
        /// Search query (separate words are joined into one query)
        #[arg(required = true)]
        query: Vec<String>,
        /// Number of results to return
        #[arg(short = 'n', long, default_value = "10")]
        top_k: usize,
    },
    /// Start a new AI coding session, optionally in a fresh git worktree
    NewSession {
        /// Agent to use: claude, gemini, aider [default: claude]
        #[arg(long, short = 'a')]
        agent: Option<String>,
        /// Create a new git worktree on this branch before launching
        #[arg(long, short = 'b')]
        branch: Option<String>,
        /// Session name (passed as -n to the agent)
        #[arg(long, short = 'n')]
        name: Option<String>,
        /// Initial prompt, also copied to clipboard
        prompt: Option<String>,
    },
    /// Resume a session, checking out a new worktree if needed
    Resume {
        /// Session ID (full UUID or unambiguous prefix)
        session_id: String,
    },
    /// Remove a session: runs `entire clean`, deletes from DB, removes search index entries
    Clean {
        /// Session ID to clean up
        session_id: String,
    },
    /// Remove git worktrees that have had no recent session activity
    Tidy {
        /// Only list stale worktrees without removing them
        #[arg(long)]
        dry_run: bool,
        /// Days of inactivity before a worktree is considered stale
        #[arg(long, default_value = "7")]
        days: i64,
        /// Pass --force to git worktree remove (removes worktrees with uncommitted changes)
        #[arg(long)]
        force: bool,
        /// Also remove sessions whose cwd was inside each removed worktree
        #[arg(long)]
        sessions: bool,
    },
    /// Attach an existing session with entireio and index it into witchcraft
    Attach {
        /// Session ID to attach
        session_id: String,
        /// Agent name passed to `entire attach`
        #[arg(short, long, default_value = "claude-code")]
        agent: String,
        /// Pass --force to `entire attach`
        #[arg(short, long)]
        force: bool,
    },
    /// Push a session's checkpoint to the remote so another agent can resume it
    Handoff {
        /// Session ID (full UUID or unambiguous prefix)
        session_id: String,
        /// Force push even if the remote has diverged
        #[arg(short, long)]
        force: bool,
    },
    /// Show or set gossamer configuration
    Config {
        /// Path to the witchcraft assets directory (enables semantic search)
        assets: Option<String>,
    },
    /// Called by the Claude Code SessionStart hook — reads JSON from stdin
    #[command(hide = true)]
    SessionStart,
    /// Called by the Claude Code Stop hook — ingests the finished session
    #[command(hide = true)]
    SessionStop,
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    let json = cli.json;
    match cli.command.unwrap_or(Commands::Repo) {
        Commands::Init => commands::init::run(json)?,
        Commands::Repo => commands::status::run(json)?,
        Commands::Sessions { all } => commands::sessions::run(all, json)?,
        Commands::Index => commands::index::run(json)?,
        Commands::Refresh => commands::refresh::run(json)?,
        Commands::Show { session } => commands::show::run(&session)?,
        Commands::Search { query, top_k } => commands::search::run(&query.join(" "), top_k, json)?,
        Commands::NewSession { agent, branch, name, prompt } => {
            commands::new_session::run(agent, branch, name, prompt)?
        }
        Commands::Resume { session_id } => commands::resume::run(&session_id)?,
        Commands::Clean { session_id } => commands::clean::run(&session_id, json)?,
        Commands::Tidy { dry_run, days, force, sessions } => commands::tidy::run(days, dry_run, force, sessions, json)?,
        Commands::Attach { session_id, agent, force } => commands::attach::run(&session_id, &agent, force, json)?,
        Commands::Handoff { session_id, force } => commands::handoff::run(&session_id, force, json)?,
        Commands::Config { assets: Some(path) } => config::set_warp_assets(&path)?,
        Commands::Config { assets: None }       => config::show(),
        Commands::SessionStart => commands::session_start::run()?,
        Commands::SessionStop  => commands::session_stop::run()?,
    }
    Ok(())
}

