1	//! Shared session-list loading for both `gossamer sessions` (top-level) and
2	//! `gossamer repo` (drilled in). Both views need the same data: DB rows from
3	//! `sessions`, augmented with fresher info from any local Claude Code JSONLs
4	//! in `~/.claude/projects`. The only thing that differs is scope.
5	
6	use chrono::{DateTime, Utc};
7	use std::io::BufRead;
8	use std::path::{Path, PathBuf};
9	
10	use crate::db;
11	use crate::entity::repository::Repository;
12	
13	pub struct DisplaySession {
14	    pub session_id: String,
15	    pub session_name: String,
16	    pub cwd: String,
17	    pub branch: String,
18	    pub updated_at: DateTime<Utc>,
19	    pub agent_name: String,
20	    pub backed_up: bool,
21	    /// Display name of whoever initiated the session — taken from the author
22	    /// of the first checkpoint (lowest checkpoint_number). Empty for sessions
23	    /// that have never been checkpointed (live JSONL only) or whose author
24	    /// couldn't be resolved.
25	    pub author: String,
26	    /// True when session_name came from an explicit `/rename` (custom-title
27	    /// entry in the JSONL); false when it's the derived first-prompt fallback.
28	    /// Drives the italic/plain distinction in the list renderers.
29	    pub name_is_explicit: bool,
30	}
31	
32	/// Collapse interior whitespace (newlines, tabs, runs of spaces) into a single
33	/// space. session_name flows into fixed-width raw-mode columns; an interior
34	/// '\n' jumps the cursor and clobbers the row layout — see git history for
35	/// the bee0c590 incident. Cheap to do everywhere session_name is produced.
36	pub fn sanitize_one_line(text: &str) -> String {
37	    let mut out = String::with_capacity(text.len());
38	    let mut prev_space = false;
39	    for c in text.chars() {
40	        if c.is_whitespace() {
41	            if !prev_space && !out.is_empty() {
42	                out.push(' ');
43	                prev_space = true;
44	            }
45	        } else {
46	            out.push(c);
47	            prev_space = false;
48	        }
49	    }
50	    while out.ends_with(' ') { out.pop(); }
51	    out
52	}
53	
54	pub enum Scope<'a> {
55	    /// All tracked sessions across every repo.
56	    All,
57	    /// Sessions belonging to a single repo. Matched primarily by `repo_id`;
58	    /// older rows without `repo_id` are caught by `cwd LIKE <directory>%`.
59	    Repo(&'a Repository),
60	}
61	
62	/// Load sessions, optionally scoped to one repo. With `include_old = false`,
63	/// only sessions updated within the last 3 days are returned. Result is sorted
64	/// most-recent-first; callers are free to re-sort.
65	pub fn fetch(scope: Scope, include_old: bool) -> Vec<DisplaySession> {
66	    let cutoff = Utc::now() - chrono::Duration::days(3);
67	    let mut sessions = query_db(&scope);
68	    // Augment first, then cutoff-filter on the final updated_at. Otherwise a
69	    // DB row with a stale updated_at but an actively-touched local JSONL gets
70	    // dropped here, then re-added as unbacked when augment can't find it —
71	    // diverging from the repo view where include_old=true skips this filter.
72	    augment_with_jsonls(&mut sessions, &scope, include_old, cutoff);
73	    if !include_old {
74	        sessions.retain(|s| s.updated_at >= cutoff);
75	    }
76	    sessions.sort_by(|a, b| b.updated_at.cmp(&a.updated_at));
77	    sessions
78	}
79	
80	fn query_db(scope: &Scope) -> Vec<DisplaySession> {
81	    let Ok(conn) = db::connect() else { return Vec::new(); };
82	    let mut out: Vec<DisplaySession> = Vec::new();
83	    let map = |row: &rusqlite::Row<'_>| -> rusqlite::Result<DisplaySession> {
84	        let ts: String = row.get(4)?;
85	        let author_name: String = row.get(6)?;
86	        let author_email: String = row.get(7)?;
87	        let os_user: String = row.get(8)?;
88	        let raw_name: String = row.get(1)?;
89	        let name_is_explicit: i64 = row.get(9)?;
90	        Ok(DisplaySession {
91	            session_id: row.get(0)?,
92	            session_name: sanitize_one_line(&raw_name),
93	            cwd: row.get(2)?,
94	            branch: row.get(3)?,
95	            updated_at: DateTime::parse_from_rfc3339(&ts)
96	                .map(|dt| dt.with_timezone(&Utc))
97	                .unwrap_or_else(|_| Utc::now()),
98	            agent_name: row.get(5)?,
99	            backed_up: true,
100	            author: resolve_author_label(&author_name, &author_email, &os_user),
101	            name_is_explicit: name_is_explicit != 0,
102	        })
103	    };
104	    // Pull the author of the FIRST checkpoint (lowest checkpoint_number) for
105	    // each session — that's whoever initiated the first message. Sessions
106	    // without checkpoints (shadow-only) get NULLs which COALESCE turns into
107	    // empty strings, leaving `author` blank.
108	    let cols = "
109	        s.session_id, s.session_name, s.cwd, COALESCE(s.branch,''),
110	        s.updated_at, s.agent_name,
111	        COALESCE(c.author_name, ''), COALESCE(c.author_email, ''), COALESCE(c.os_user, ''),
112	        s.name_is_explicit
113	    ";
114	    let join = "
115	        LEFT JOIN checkpoints c
116	          ON c.session_id = s.session_id
117	         AND c.checkpoint_number = (
118	               SELECT MIN(checkpoint_number) FROM checkpoints WHERE session_id = s.session_id
119	             )
120	    ";
121	    match scope {
122	        Scope::All => {
123	            let Ok(mut stmt) = conn.prepare(
124	                &format!("SELECT {cols} FROM sessions s {join} ORDER BY s.updated_at DESC")
125	            ) else { return out; };
126	            if let Ok(rows) = stmt.query_map([], map) {
127	                for r in rows.flatten() { out.push(r); }
128	            }
129	        }
130	        Scope::Repo(r) => {
131	            let Ok(mut stmt) = conn.prepare(&format!(
132	                "SELECT {cols} FROM sessions s {join}
133	                 WHERE s.repo_id = ?1 OR (s.repo_id IS NULL AND s.cwd LIKE ?2)
134	                 ORDER BY s.updated_at DESC"
135	            )) else { return out; };
136	            let pattern = format!("{}%", r.directory);
137	            if let Ok(rows) = stmt.query_map(rusqlite::params![r.id as i64, pattern], map) {
138	                for row in rows.flatten() { out.push(row); }
139	            }
140	        }
141	    }
142	    out
143	}
144	
145	fn cwd_os_user(cwd: &str) -> Option<String> {
146	    let rest = cwd.strip_prefix("/Users/").or_else(|| cwd.strip_prefix("/home/"))?;
147	    let user = rest.split('/').next()?;
148	    if user.is_empty() { None } else { Some(user.to_string()) }
149	}
150	
151	fn resolve_author_label(name: &str, email: &str, os_user: &str) -> String {
152	    if !name.trim().is_empty() { return name.to_string(); }
153	    if !email.trim().is_empty() { return email.to_string(); }
154	    if !os_user.trim().is_empty() { return os_user.to_string(); }
155	    String::new()
156	}
157	
158	fn augment_with_jsonls(
159	    sessions: &mut Vec<DisplaySession>,
160	    scope: &Scope,
161	    include_old: bool,
162	    cutoff: DateTime<Utc>,
163	) {
164	    let Ok(home) = std::env::var("HOME") else { return; };
