60	fn detect() -> Theme {
61	    // Explicit override wins
62	    if let Ok(v) = std::env::var("GOSSAMER_THEME") {
63	        match v.to_lowercase().as_str() {
64	            "light" => return light(),
65	            "dark"  => return dark(),
66	            _ => {}
67	        }
68	    }
69	
70	    // Query the terminal directly for its background colour (OSC 11). Works in
71	    // iTerm2, Terminal.app, Alacritty, Kitty, WezTerm, foot, modern xterm, etc.
72	    if let Some(luma) = query_terminal_luma() {
73	        return if luma > 0.5 { light() } else { dark() };
74	    }
75	
76	    // COLORFGBG="fg;bg" — set by rxvt and a few configs; background index 7
77	    // (white) or 15 (bright white) means a light terminal.
78	    if let Ok(v) = std::env::var("COLORFGBG") {
79	        if let Some(bg) = v.rsplit(';').next().and_then(|s| s.trim().parse::<u8>().ok()) {
80	            if bg == 7 || bg == 15 {
81	                return light();
82	            }
83	        }
84	    }
85	
86	    dark()
