89	/// Query the controlling terminal for its background colour via OSC 11 and
90	/// return the perceived luminance (0.0 = black, 1.0 = white). Returns None if
91	/// we couldn't talk to a terminal or the response didn't parse.
92	#[cfg(unix)]
93	fn query_terminal_luma() -> Option<f32> {
94	    use std::io::{Read, Write};
95	    use std::os::unix::io::AsRawFd;
96	    use std::time::Instant;
97	
98	    // Open /dev/tty so we work even when stdout is redirected.
99	    let mut tty = std::fs::OpenOptions::new()
100	        .read(true)
101	        .write(true)
102	        .open("/dev/tty")
103	        .ok()?;
104	    let fd = tty.as_raw_fd();
105	
106	    // Snapshot termios so we can restore it.
107	    let mut orig: libc::termios = unsafe { std::mem::zeroed() };
108	    if unsafe { libc::tcgetattr(fd, &mut orig) } != 0 {
109	        return None;
110	    }
111	    let mut raw = orig;
112	    unsafe { libc::cfmakeraw(&mut raw) };
113	    if unsafe { libc::tcsetattr(fd, libc::TCSANOW, &raw) } != 0 {
114	        return None;
115	    }
116	
117	    // Send the query and read the response with a short timeout. Some
118	    // terminals (older tmux, screen without DCS passthrough) won't reply, so
119	    // we have to bail quickly to avoid stalling the TUI.
120	    let _ = tty.write_all(b"\x1b]11;?\x1b\\");
121	    let _ = tty.flush();
122	
123	    let mut buf: Vec<u8> = Vec::with_capacity(64);
124	    let mut chunk = [0u8; 64];
125	    let timeout_ms: i32 = 150;
126	    let start = Instant::now();
127	
128	    loop {
129	        let elapsed = start.elapsed().as_millis() as i32;
130	        let remaining = timeout_ms - elapsed;
131	        if remaining <= 0 {
132	            break;
133	        }
134	        let mut pfd = libc::pollfd {
135	            fd,
136	            events: libc::POLLIN,
137	            revents: 0,
138	        };
139	        let n = unsafe { libc::poll(&mut pfd, 1, remaining) };
140	        if n <= 0 {
141	            break;
142	        }
143	        let r = match tty.read(&mut chunk) {
144	            Ok(0) | Err(_) => break,
145	            Ok(r) => r,
146	        };
147	        buf.extend_from_slice(&chunk[..r]);
148	        // Response terminates with BEL (0x07) or ST (ESC \).
149	        if buf.contains(&0x07) || buf.windows(2).any(|w| w == b"\x1b\\") {
150	            break;
151	        }
152	    }
153	
154	    // Restore termios no matter what.
155	    unsafe { libc::tcsetattr(fd, libc::TCSANOW, &orig) };
156	
157	    parse_osc11_luma(&buf)
158	}
159	
160	#[cfg(not(unix))]
161	fn query_terminal_luma() -> Option<f32> {
162	    None
163	}
164	
165	/// Parse `\x1b]11;rgb:RRRR/GGGG/BBBB\x07` (lengths may be 1-4 hex digits per
166	/// channel) and return relative luminance.
167	fn parse_osc11_luma(buf: &[u8]) -> Option<f32> {
168	    let s = std::str::from_utf8(buf).ok()?;
169	    let rest = s.split("rgb:").nth(1)?;
170	    let mut parts = rest.split('/');
171	    let r = parse_hex_channel(parts.next()?)?;
172	    let g = parse_hex_channel(parts.next()?)?;
173	    let b = parse_hex_channel(parts.next()?)?;
174	    // Rec. 709 luminance is a fine proxy for "is this a light or dark bg".
175	    Some(0.2126 * r + 0.7152 * g + 0.0722 * b)
176	}
177	
178	fn parse_hex_channel(s: &str) -> Option<f32> {
179	    let hex: String = s.chars().take_while(|c| c.is_ascii_hexdigit()).collect();
180	    if hex.is_empty() {
181	        return None;
182	    }
183	    let raw = u32::from_str_radix(&hex, 16).ok()?;
184	    // Normalise: 1-hex => /15, 2-hex => /255, 4-hex => /65535, etc.
185	    let max = (1u32 << (4 * hex.len() as u32)).saturating_sub(1).max(1);
186	    Some(raw as f32 / max as f32)
187	}
188	
189	pub fn dark() -> Theme {
190	    Theme {
191	        sel_bg:         "48;5;236",
192	        text_dim:       "38;5;240",
193	        text_faint:     "38;5;238",
194	        text_primary:   "38;5;255",
195	        text_secondary: "38;5;245",
196	        fresh:          "38;5;82",
