155	    let cwd = env::current_dir().ok().map(|p| p.to_string_lossy().to_string());
156	    let current_repo_dir = cwd.as_deref().and_then(|cwd| {
157	        repos.iter().find(|r| cwd.starts_with(r.directory.as_str())).map(|r| r.directory.as_str())
158	    });
159	
160	    let start_sel = cwd.as_deref()
161	        .and_then(|cwd| repos.iter().position(|r| cwd.starts_with(r.directory.as_str())))
162	        .unwrap_or(0);
163	
164	    let initial = if let Some(idx) = start_repo.filter(|&i| i < repos.len()) {
165	        let sessions = session_list::fetch(Scope::Repo(&repos[idx]), true);
166	        let worktrees = fetch_worktrees(&repos[idx].directory);
167	        Screen::Sessions { repo_idx: idx, sel: 0, sessions, worktrees }
168	    } else {
169	        Screen::Repos { sel: start_sel }
170	    };
171	
172	    // Navigation stack — back pops; when empty the TUI exits.
173	    let mut stack: Vec<Screen> = vec![initial];
174	
175	    // Commands produced inside match arms, executed after the borrow ends.
176	    enum Cmd {
177	        None,
178	        Break,
179	        Back,
180	        PushSessions(usize),
181	        Cd(String),
182	        ShowSession(String),
183	        ResumeSession(String, String), // (session_id, repo_dir)
184	        Search(String),
185	        NewWorktree(String), // branch name
186	        NewSession(NewSessionConfig),
187	        Tidy,
188	        Redraw,
189	    }
190	
191	    loop {
192	        let (w, h) = terminal::size().unwrap_or((120, 40));
193	        let w = w as usize;
194	        let h = h as usize;
195	
196	        match stack.last().unwrap() {
197	            Screen::Repos { sel } => draw_repos(stdout, repos, *sel, current_repo_dir, w, h, has_cd)?,
198	            Screen::Sessions { repo_idx, sel, sessions, worktrees } => {
199	                draw_sessions(stdout, repos, *repo_idx, sessions, worktrees, *sel, w, h)?
200	            }
201	        }
202	
203	        let cmd = match event::read()? {
204	            Event::Key(k) => match stack.last_mut().unwrap() {
205	                Screen::Repos { sel } => match k.code {
206	                    KeyCode::Char('q') | KeyCode::Esc => Cmd::Break,
207	                    KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
208	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
209	                        terminal::disable_raw_mode().ok();
210	                        std::process::exit(0);
211	                    }
212	                    KeyCode::Up   | KeyCode::Char('k') => { if *sel > 0 { *sel -= 1; } Cmd::None }
213	                    KeyCode::Down | KeyCode::Char('j') => { if *sel + 1 < repos.len() { *sel += 1; } Cmd::None }
214	                    KeyCode::Char('g') => { *sel = 0; Cmd::None }
215	                    KeyCode::Char('G') => { *sel = repos.len().saturating_sub(1); Cmd::None }
216	                    KeyCode::Char(' ') | KeyCode::Right => Cmd::PushSessions(*sel),
217	                    KeyCode::Char('c') if has_cd => Cmd::Cd(repos[*sel].directory.clone()),
218	                    KeyCode::Char('s') => {
219	                        let repo_dir = repos[*sel].directory.clone();
220	                        match new_session_wizard(stdout, &repo_dir, w, h) {
221	                            Some(cfg) => Cmd::NewSession(cfg),
222	                            None => Cmd::Redraw,
223	                        }
224	                    }
225	                    KeyCode::Char('/') => match collect_search_query(stdout, w, h) {
226	                        Some(q) if !q.trim().is_empty() => Cmd::Search(q),
227	                        _ => Cmd::Redraw,
228	                    },
229	                    _ => Cmd::None,
230	                },
231	                Screen::Sessions { sel, sessions, repo_idx, .. } => match k.code {
232	                    KeyCode::Char('q') => Cmd::Break,
233	                    KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
234	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
235	                        terminal::disable_raw_mode().ok();
236	                        std::process::exit(0);
237	                    }
238	                    KeyCode::Esc | KeyCode::Char('h') | KeyCode::Left => Cmd::Back,
239	                    KeyCode::Up   | KeyCode::Char('k') => { if *sel > 0 { *sel -= 1; } Cmd::None }
240	                    KeyCode::Down | KeyCode::Char('j') => { if *sel + 1 < sessions.len() { *sel += 1; } Cmd::None }
241	                    KeyCode::Char('g') => { *sel = 0; Cmd::None }
242	                    KeyCode::Char('G') => { *sel = sessions.len().saturating_sub(1); Cmd::None }
243	                    KeyCode::Char(' ') | KeyCode::Right => {
244	                        if sessions.is_empty() { Cmd::None }
245	                        else { Cmd::ShowSession(sessions[*sel].session_id.clone()) }
246	                    }
247	                    KeyCode::Char('r') => {
248	                        if sessions.is_empty() { Cmd::None }
249	                        else { Cmd::ResumeSession(sessions[*sel].session_id.clone(), repos[*repo_idx].directory.clone()) }
250	                    }
251	                    KeyCode::Char('/') => match collect_search_query(stdout, w, h) {
252	                        Some(q) if !q.trim().is_empty() => Cmd::Search(q),
253	                        _ => Cmd::Redraw,
254	                    },
255	                    KeyCode::Char('n') => match collect_text_input(stdout, "  new worktree branch: ", w, h) {
256	                        Some(b) if !b.trim().is_empty() => Cmd::NewWorktree(b.trim().to_string()),
257	                        _ => Cmd::Redraw,
258	                    },
259	                    KeyCode::Char('s') => {
260	                        let repo_dir = repos[*repo_idx].directory.clone();
261	                        match new_session_wizard(stdout, &repo_dir, w, h) {
262	                            Some(cfg) => Cmd::NewSession(cfg),
263	                            None => Cmd::Redraw,
264	                        }
265	                    }
266	                    KeyCode::Char('t') => Cmd::Tidy,
267	                    _ => Cmd::None,
268	                },
269	            },
270	            Event::Resize(_, _) => Cmd::Redraw,
271	            _ => Cmd::None,
272	        };
273	
274	        match cmd {
275	            Cmd::None => {}
276	            Cmd::Break => break,
277	            Cmd::Back => {
278	                stack.pop();
279	                if stack.is_empty() { break; }
280	            }
281	            Cmd::PushSessions(idx) => {
282	                let sessions = session_list::fetch(Scope::Repo(&repos[idx]), true);
283	                let worktrees = fetch_worktrees(&repos[idx].directory);
284	                stack.push(Screen::Sessions { repo_idx: idx, sel: 0, sessions, worktrees });
285	            }
286	            Cmd::Cd(path) => return Ok(Some(TuiOutcome::CdTo(path))),
287	            Cmd::ResumeSession(id, cwd) => return Ok(Some(TuiOutcome::ResumeSession { id, cwd })),
288	            Cmd::ShowSession(id) => {
289	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
290	                terminal::disable_raw_mode().ok();
291	                let _ = super::show::run(&id);
292	                terminal::enable_raw_mode().ok();
293	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
294	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
295	            }
296	            Cmd::Search(query) => {
297	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
298	                terminal::disable_raw_mode().ok();
299	                let _ = super::search::run(&query, 10, false);
300	                terminal::enable_raw_mode().ok();
301	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
302	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
303	            }
304	            Cmd::NewWorktree(branch) => {
305	                if let Some(Screen::Sessions { repo_idx, worktrees, .. }) = stack.last_mut() {
306	                    let repo_dir = &repos[*repo_idx].directory;
307	                    let notification = create_worktree(repo_dir, &branch);
308	                    // Refresh the worktree list whether or not it succeeded.
309	                    *worktrees = fetch_worktrees(repo_dir);
310	                    // Show the result in the status bar until the next keypress.
311	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
312	                    let msg: String = notification.chars().take(tw as usize).collect();
313	                    let padded = format!("{:<width$}", msg, width = tw as usize);
314	                    execute!(stdout, cursor::MoveTo(0, th - 1)).ok();
315	                    write!(stdout, "\x1b[7m{padded}\x1b[0m").ok();
316	                    stdout.flush().ok();
317	                }
318	            }
319	            Cmd::NewSession(cfg) => {
320	                // Create worktree if requested, then launch the agent.
321	                let launch_dir = if let Some(ref branch) = cfg.branch {
322	                    let _ = create_worktree(&cfg.repo_dir, branch);
323	                    if let Some(Screen::Sessions { repo_idx, worktrees, .. }) = stack.last_mut() {
324	                        *worktrees = fetch_worktrees(&repos[*repo_idx].directory);
325	                    }
326	                    let repo_path = std::path::Path::new(&cfg.repo_dir);
327	                    let parent = repo_path.parent().unwrap_or(repo_path);
328	                    let repo_name = repo_path.file_name()
329	                        .map(|s| s.to_string_lossy().to_string())
330	                        .unwrap_or_else(|| "repo".to_string());
331	                    parent.join(format!("{repo_name}-{}", branch)).to_string_lossy().to_string()
332	                } else {
333	                    cfg.repo_dir.clone()
334	                };
335	
336	                // Copy prompt to clipboard as a convenience.
337	                let prompt = cfg.prompt.trim().to_string();
338	                if !prompt.is_empty() {
339	                    if let Ok(mut child) = std::process::Command::new("pbcopy")
340	                        .stdin(std::process::Stdio::piped())
341	                        .spawn()
342	                    {
343	                        if let Some(stdin) = child.stdin.as_mut() {
344	                            let _ = stdin.write_all(prompt.as_bytes());
345	                        }
346	                        let _ = child.wait();
347	                    }
348	                }
349	
350	                let session_name = cfg.session_name.trim().to_string();
351	                return Ok(Some(TuiOutcome::LaunchAgent {
352	                    cli: cfg.agent_cli,
353	                    cwd: launch_dir,
354	                    session_name,
355	                    prompt,
356	                }));
357	            }
358	            Cmd::Tidy => {
359	                let repo_idx_opt = if let Some(Screen::Sessions { repo_idx, .. }) = stack.last() {
360	                    Some(*repo_idx)
361	                } else {
362	                    None
363	                };
364	                if let Some(repo_idx) = repo_idx_opt {
365	                    let repo = &repos[repo_idx];
366	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
367	                    let changed = super::tidy::tui_tidy(
368	                        stdout,
369	                        std::slice::from_ref(repo),
370	                        7,
371	                        false,
372	                        tw as usize,
373	                        th as usize,
374	                    );
375	                    if changed {
376	                        if let Some(Screen::Sessions { worktrees, .. }) = stack.last_mut() {
377	                            *worktrees = fetch_worktrees(&repos[repo_idx].directory);
378	                        }
379	                    }
380	                    execute!(stdout, terminal::Clear(ClearType::All)).ok();
381	                }
382	            }
383	            Cmd::Redraw => { execute!(stdout, terminal::Clear(ClearType::All)).ok(); }
384	        }
385	    }
386	
387	    Ok(None)
388	}
