391	
392	fn draw_repos(
393	    stdout: &mut impl Write,
394	    repos: &[Repository],
395	    sel: usize,
396	    current_repo_dir: Option<&str>,
397	    w: usize,
398	    h: usize,
399	    has_cd: bool,
400	) -> io::Result<()> {
401	    let t = crate::theme::get();
402	    let sel_bg = t.sel_bg;
403	
404	    execute!(stdout, cursor::MoveTo(0, 0))?;
405	
406	    let content_h = h.saturating_sub(1);
407	    let mut row = 0usize;
408	
409	    let name_w = repos.iter().map(|r| r.name.chars().count()).max().unwrap_or(0);
410	    let dir_w  = repos.iter().map(|r| r.directory.chars().count()).max().unwrap_or(0);
411	
412	    for (i, repo) in repos.iter().enumerate() {
413	        if row >= content_h { break }
414	
415	        let is_sel = i == sel;
416	        let is_cur = current_repo_dir == Some(repo.directory.as_str());
417	        let dot_col = if is_cur { t.fresh } else { t.text_dim };
418	
419	        let name_padded = format!("{:<name_w$}", repo.name);
420	        let dir_padded  = format!("{:<dir_w$}",  repo.directory);
421	        let line = format!(
422	            "\x1b[{dot_col}m*\x1b[0m \x1b[{pm}m{name_padded}\x1b[0m  \x1b[{dm}m{dir_padded}  {}\x1b[0m",
423	            repo.remote, pm = t.text_primary, dm = t.text_dim,
424	        );
425	
426	        print_row(stdout, &line, is_sel, sel_bg, w, row as u16)?;
427	        row += 1;
428	    }
429	
430	    // Clear remaining rows
431	    while row < content_h {
432	        execute!(stdout, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
433	        row += 1;
434	    }
435	
436	    // Status bar
437	    let cd_hint = if has_cd { "   c: cd" } else { "" };
438	    let bar = format!(
439	        "  {} repos   ↑↓/jk navigate   space: sessions   s: new session   /: search{}   q: quit  ",
440	        repos.len(), cd_hint
441	    );
442	    draw_status(stdout, &bar, w, h)?;
443	
444	    stdout.flush()
445	}
446	
447	fn draw_sessions(
448	    stdout: &mut impl Write,
449	    repos: &[Repository],
450	    repo_idx: usize,
451	    sessions: &[RepoSession],
452	    worktrees: &[RepoWorktree],
453	    sel: usize,
454	    w: usize,
455	    h: usize,
456	) -> io::Result<()> {
457	    let t = crate::theme::get();
458	    let sel_bg = t.sel_bg;
459	
460	    execute!(stdout, cursor::MoveTo(0, 0))?;
461	    write!(stdout, "\x1b[{hd}m{}\x1b[0m", repos[repo_idx].name, hd = t.header)?;
462	    execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
463	
464	    let content_h = h.saturating_sub(2); // header + status bar
465	    let mut row = 1usize;
466	
467	    // ── Worktrees ────────────────────────────────────────────────────────────
468	    if !worktrees.is_empty() {
469	        for wt in worktrees.iter().take(content_h.saturating_sub(row + 1)) {
470	            if row >= content_h { break; }
471	
472	            let (branch_col, branch_label) = if wt.branch == "(detached)" {
473	                (t.error, format!("detached:{}", &wt.head))
474	            } else if wt.is_main {
475	                (t.accent, wt.branch.clone())
476	            } else {
477	                (t.link, wt.branch.clone())
478	            };
479	
480	            let path_short = short_path_s(&wt.path);
481	            let line = format!(
482	                "\x1b[{dm}m  @ \x1b[{branch_col}m{branch_label}\x1b[0m  \x1b[{dm}m{path_short}\x1b[0m",
483	                dm = t.text_dim,
484	            );
485	            execute!(stdout, cursor::MoveTo(0, row as u16))?;
486	            write!(stdout, "{line}")?;
487	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
488	            row += 1;
489	        }
490	
491	        // Blank separator between worktrees and sessions
492	        if row < content_h {
493	            execute!(stdout, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
494	            row += 1;
495	        }
496	    }
497	
498	    // ── Sessions ─────────────────────────────────────────────────────────────
499	    let sessions_start = row;
500	    let sessions_h = content_h.saturating_sub(sessions_start);
501	    let scroll = if sel >= sessions_h { sel + 1 - sessions_h } else { 0 };
502	
503	    if sessions.is_empty() {
504	        if row < content_h {
505	            execute!(stdout, cursor::MoveTo(0, row as u16))?;
506	            write!(stdout, "\x1b[{dm}m  no sessions found\x1b[0m", dm = t.text_dim)?;
507	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
508	            row += 1;
509	        }
510	    } else {
511	        // Pre-compute column widths for table alignment
512	        let name_w   = sessions.iter().map(|s| s.session_name.trim().chars().count()).max().unwrap_or(0).min(40);
513	        let branch_w = sessions.iter().map(|s| s.branch.chars().count()).max().unwrap_or(0);
514	        let author_w = sessions.iter().map(|s| s.author.chars().count()).max().unwrap_or(0);
515	        let agent_w  = sessions.iter().map(|s| s.agent_name.chars().count()).max().unwrap_or(0);
516	
517	        for (i, s) in sessions.iter().enumerate().skip(scroll) {
518	            if row >= content_h { break; }
519	
520	            let id_short: String = s.session_id.chars().take(8).collect();
521	            let ts = relative_time(s.updated_at);
522	            let clean = session_list::sanitize_one_line(&s.session_name);
523	            let name: String = clean.chars().take(name_w).collect();
524	            let age = (Utc::now() - s.updated_at).num_seconds().max(0);
525	            let dot_col = match age {
526	                a if a < 900   => t.fresh,
527	                a if a < 3_600 => t.moderate,
528	                _              => t.text_dim,
529	            };
530	
531	            let (name_col, meta_col, dot_char) = if s.backed_up {
532	                (t.backed_name, t.backed_meta, "*")
533	            } else {
534	                (t.unbacked_name, t.unbacked_meta, "·")
535	            };
536	            // Derived names (first-prompt fallback) render in the secondary
537	            // color so they're visually distinct from /rename'd titles.
538	            let name_col = if s.backed_up && !s.name_is_explicit { t.text_secondary } else { name_col };
539	            let branch_col = if s.backed_up { t.link } else { t.stale };
540	
541	            let name_padded = format!("{:<name_w$}", name);
542	            let mut line = format!("\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m");
543	
544	            if branch_w > 0 {
545	                let b: String = s.branch.chars().take(branch_w).collect();
546	                let pad = " ".repeat(branch_w - b.chars().count());
547	                line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
548	            }
549	
550	            if author_w > 0 {
551	                let a: String = s.author.chars().take(author_w).collect();
552	                let pad = " ".repeat(author_w - a.chars().count());
553	                line.push_str(&format!("  \x1b[{dm}m{a}{pad}\x1b[0m", dm = t.text_dim));
554	            }
555	
556	            if agent_w > 0 {
557	                let col = if s.backed_up { agent_color(&s.agent_name) } else { t.stale_agent };
558	                let a: String = s.agent_name.chars().take(agent_w).collect();
559	                let pad = " ".repeat(agent_w - a.chars().count());
560	                line.push_str(&format!("  \x1b[38;5;{col}m{a}{pad}\x1b[0m"));
561	            }
562	
563	            line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
564	
565	            print_row(stdout, &line, i == sel, sel_bg, w, row as u16)?;
566	            row += 1;
567	        }
568	    }
569	
570	    while row < content_h {
571	        execute!(stdout, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
572	        row += 1;
573	    }
574	
575	    let bar = format!(
576	        "  {} sessions   ↑↓/jk navigate   space: view   r: resume   s: new session   n: new worktree   t: tidy   /: search   ←/h: back   q: quit  ",
577	        sessions.len()
578	    );
579	    draw_status(stdout, &bar, w, h)?;
580	
581	    stdout.flush()
582	}
583	
584	fn print_row(stdout: &mut impl Write, line: &str, selected: bool, bg: &str, w: usize, row: u16) -> io::Result<()> {
585	    execute!(stdout, cursor::MoveTo(0, row))?;
586	    if selected {
587	        let colored = with_bg(line, bg);
588	        let vis = visible_width(line);
589	        let pad = w.saturating_sub(vis);
590	        write!(stdout, "\x1b[{bg}m{colored}{}\x1b[0m", " ".repeat(pad))?;
591	    } else {
592	        write!(stdout, "{line}")?;
593	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
594	    }
595	    Ok(())
596	}
597	
598	fn draw_status(stdout: &mut impl Write, bar: &str, w: usize, h: usize) -> io::Result<()> {
599	    let display: String = bar.chars().take(w).collect();
600	    let padded = format!("{:<width$}", display, width = w);
601	    execute!(stdout, cursor::MoveTo(0, (h - 1) as u16))?;
602	    write!(stdout, "\x1b[7m{padded}\x1b[0m")
603	}
