605	// ── Worktree loading ──────────────────────────────────────────────────────────
606	
607	fn fetch_worktrees(repo_dir: &str) -> Vec<RepoWorktree> {
608	    let out = std::process::Command::new("git")
609	        .args(["worktree", "list", "--porcelain"])
610	        .current_dir(repo_dir)
611	        .output();
612	
613	    let Ok(out) = out else { return vec![]; };
614	    if !out.status.success() { return vec![]; }
615	    let text = String::from_utf8_lossy(&out.stdout);
616	
617	    let mut result = Vec::new();
618	    let mut first = true;
619	
620	    // Each worktree block is separated by a blank line.
621	    for block in text.split("\n\n") {
622	        let mut path = String::new();
623	        let mut head = String::new();
624	        let mut branch = String::new();
625	        let mut detached = false;
626	
627	        for line in block.lines() {
628	            if let Some(v) = line.strip_prefix("worktree ") {
629	                path = v.to_string();
630	            } else if let Some(v) = line.strip_prefix("HEAD ") {
631	                head = v.chars().take(8).collect();
632	            } else if let Some(v) = line.strip_prefix("branch refs/heads/") {
633	                branch = v.to_string();
634	            } else if line == "detached" {
635	                detached = true;
636	            }
637	        }
638	
639	        if path.is_empty() { continue; }
640	        if detached { branch = "(detached)".to_string(); }
641	        if branch.is_empty() { continue; } // bare worktree — skip
642	
643	        result.push(RepoWorktree { path, branch, head, is_main: first });
644	        first = false;
645	    }
646	
647	    result
648	}
