653	
654	/// Generic single-line input shown in the status bar. Returns None on Esc.
655	fn collect_text_input(stdout: &mut impl Write, prefix: &str, w: usize, h: usize) -> Option<String> {
656	    let mut value = String::new();
657	    execute!(stdout, cursor::Show).ok();
658	    draw_input_bar(stdout, prefix, &value, w, h).ok();
659	
660	    loop {
661	        match event::read().ok()? {
662	            Event::Key(k) => match k.code {
663	                KeyCode::Esc => {
664	                    execute!(stdout, cursor::Hide).ok();
665	                    return None;
666	                }
667	                KeyCode::Enter => {
668	                    execute!(stdout, cursor::Hide).ok();
669	                    return Some(value);
670	                }
671	                KeyCode::Backspace => {
672	                    value.pop();
673	                    draw_input_bar(stdout, prefix, &value, w, h).ok();
674	                }
675	                KeyCode::Char(c) => {
676	                    value.push(c);
677	                    draw_input_bar(stdout, prefix, &value, w, h).ok();
678	                }
679	                _ => {}
680	            },
681	            _ => {}
682	        }
683	    }
684	}
685	
686	fn draw_input_bar(stdout: &mut impl Write, prefix: &str, value: &str, w: usize, h: usize) -> io::Result<()> {
687	    let prefix_len = prefix.chars().count();
688	    let text: String = value.chars().take(w.saturating_sub(prefix_len + 2)).collect();
689	    let content = format!("{prefix}{text}");
690	    let padded = format!("{:<width$}", content, width = w);
691	    execute!(stdout, cursor::MoveTo(0, (h - 1) as u16))?;
692	    write!(stdout, "\x1b[7m{padded}\x1b[0m")?;
693	    let col = (prefix_len + text.chars().count()).min(w.saturating_sub(1)) as u16;
694	    execute!(stdout, cursor::MoveTo(col, (h - 1) as u16))?;
695	    stdout.flush()
696	}
697	
698	fn collect_search_query(stdout: &mut impl Write, w: usize, h: usize) -> Option<String> {
699	    collect_text_input(stdout, "  / ", w, h)
700	}
701	
702	// ── New session wizard ────────────────────────────────────────────────────────
703	
704	/// A 4-step panel drawn over the bottom of the screen. Each completed step
705	/// stays visible with its confirmed value while the user fills the next one.
706	fn new_session_wizard(stdout: &mut impl Write, repo_dir: &str, w: usize, h: usize) -> Option<NewSessionConfig> {
707	    const LABEL_W: usize = 24;
708	    // Panel rows: title, blank, agent, branch, name, prompt, blank  (7 rows + 1 status bar)
709	    const PANEL_H: usize = 7;
710	
711	    let t = crate::theme::get();
712	    let panel_top = h.saturating_sub(PANEL_H + 1);
713	
714	    let mut step = 0usize;           // 0=agent 1=branch 2=name 3=prompt
715	    let mut agent_sel = 0usize;
716	    let mut confirmed_agent = 0usize;
717	    let mut inputs = [String::new(), String::new(), String::new()]; // branch, name, prompt
718	
719	    execute!(stdout, cursor::Show).ok();
720	
721	    loop {
722	        // ── Draw panel ────────────────────────────────────────────────────────
723	        // Title row
724	        execute!(stdout, cursor::MoveTo(0, panel_top as u16)).ok();
725	        write!(stdout, "\x1b[{hd}m  New Session\x1b[0m", hd = t.header).ok();
726	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
727	
728	        // Blank separator
729	        execute!(stdout, cursor::MoveTo(0, (panel_top + 1) as u16)).ok();
730	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
731	
732	        let step_rows  = [panel_top + 2, panel_top + 3, panel_top + 4, panel_top + 5];
733	        let step_labels = ["  Agent", "  Worktree branch", "  Session name", "  Prompt"];
734	
735	        for (i, (&row, &label)) in step_rows.iter().zip(step_labels.iter()).enumerate() {
736	            execute!(stdout, cursor::MoveTo(0, row as u16)).ok();
737	            let lpart = format!("{label:<LABEL_W$}");
738	
739	            if i < step {
740	                // Completed — dim label, value in colour
741	                let val = if i == 0 {
742	                    let (name, _, col) = AGENTS[confirmed_agent];
743	                    format!("\x1b[38;5;{col}m{name}\x1b[0m")
744	                } else {
745	                    let v = inputs[i - 1].trim();
746	                    if v.is_empty() { format!("\x1b[{ft}m(skip)\x1b[0m", ft = t.text_faint) }
747	                    else            { format!("\x1b[{pm}m{v}\x1b[0m", pm = t.text_primary) }
748	                };
749	                write!(stdout, "\x1b[{dm}m{lpart}\x1b[0m{val}", dm = t.text_dim).ok();
750	            } else if i == step {
751	                // Active step
752	                write!(stdout, "\x1b[{pm}m{lpart}\x1b[0m", pm = t.text_primary).ok();
753	                if i == 0 {
754	                    // Inline agent picker
755	                    for (ai, (name, _, col)) in AGENTS.iter().enumerate() {
756	                        if ai > 0 { write!(stdout, "\x1b[{ft}m │ \x1b[0m", ft = t.text_faint).ok(); }
757	                        if ai == agent_sel {
758	                            write!(stdout, "\x1b[{sb};38;5;{col}m {name} \x1b[0m", sb = t.sel_bg).ok();
759	                        } else {
760	                            write!(stdout, "\x1b[{dm}m {name}\x1b[0m", dm = t.text_dim).ok();
761	                        }
762	                    }
763	                } else {
764	                    // Text input — print typed chars, terminal cursor sits here
765	                    write!(stdout, "\x1b[{pm}m{}\x1b[0m", inputs[i - 1], pm = t.text_primary).ok();
766	                }
767	            } else {
768	                // Future step — very dim label only
769	                write!(stdout, "\x1b[{ft}m{lpart}\x1b[0m", ft = t.text_faint).ok();
770	            }
771	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
772	        }
773	
774	        // Trailing blank row
775	        let blank2 = panel_top + 6;
776	        if blank2 < h.saturating_sub(1) {
777	            execute!(stdout, cursor::MoveTo(0, blank2 as u16)).ok();
778	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
779	        }
780	
781	        // Status bar hint
782	        let bar = if step == 0 {
783	            "  ↑↓/jk: select agent   enter: confirm   esc: cancel  "
784	        } else {
785	            "  type to enter   enter: next   esc: cancel  "
786	        };
787	        draw_status(stdout, bar, w, h).ok();
788	
789	        // Position terminal cursor for text input steps
790	        if step > 0 {
791	            let row = step_rows[step];
792	            let col = (LABEL_W + inputs[step - 1].len()).min(w.saturating_sub(1));
793	            execute!(stdout, cursor::MoveTo(col as u16, row as u16)).ok();
794	        }
795	        stdout.flush().ok();
796	
797	        // ── Handle input ──────────────────────────────────────────────────────
798	        match event::read().ok()? {
799	            Event::Key(k) => match k.code {
800	                KeyCode::Esc => {
801	                    execute!(stdout, cursor::Hide).ok();
802	                    return None;
803	                }
804	                KeyCode::Up   | KeyCode::Char('k') if step == 0 => {
805	                    if agent_sel > 0 { agent_sel -= 1; }
806	                }
807	                KeyCode::Down | KeyCode::Char('j') if step == 0 => {
808	                    if agent_sel + 1 < AGENTS.len() { agent_sel += 1; }
809	                }
810	                KeyCode::Backspace if step > 0 => {
811	                    inputs[step - 1].pop();
812	                }
813	                KeyCode::Char(c) if step > 0 && !k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
814	                    inputs[step - 1].push(c);
815	                }
816	                KeyCode::Enter => match step {
817	                    0 => { confirmed_agent = agent_sel; step = 1; }
818	                    1 | 2 => { step += 1; }
819	                    _ => {
820	                        execute!(stdout, cursor::Hide).ok();
821	                        let (agent_name, agent_cli, _) = AGENTS[confirmed_agent];
822	                        let branch_raw = inputs[0].trim().to_string();
823	                        return Some(NewSessionConfig {
824	                            agent_name: agent_name.to_string(),
825	                            agent_cli: agent_cli.to_string(),
826	                            branch: if branch_raw.is_empty() { None } else { Some(branch_raw) },
827	                            session_name: inputs[1].trim().to_string(),
828	                            prompt: inputs[2].trim().to_string(),
829	                            repo_dir: repo_dir.to_string(),
830	                        });
831	                    }
832	                },
833	                _ => {}
834	            },
835	            _ => {}
836	        }
837	    }
838	}
839	
840	// ── Helpers ───────────────────────────────────────────────────────────────────
841	
842	fn create_worktree(repo_dir: &str, branch: &str) -> String {
843	    let repo_path = std::path::Path::new(repo_dir);
844	    let parent = match repo_path.parent() {
845	        Some(p) => p,
846	        None => return "Error: cannot determine repo parent directory".to_string(),
847	    };
848	    let repo_name = repo_path
849	        .file_name()
850	        .map(|s| s.to_string_lossy().to_string())
851	        .unwrap_or_else(|| "repo".to_string());
852	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
853	
854	    // Try -b (new branch) first; fall back to checking out an existing branch.
855	    let out = std::process::Command::new("git")
856	        .args(["worktree", "add", "-b", branch, wt_path.to_str().unwrap_or("")])
857	        .current_dir(repo_dir)
858	        .output();
859	
860	    match out {
861	        Err(e) => format!("Error: {e}"),
862	        Ok(o) if o.status.success() => {
863	            format!("Created worktree: {}", short_path_s(wt_path.to_str().unwrap_or("")))
864	        }
865	        Ok(o) => {
866	            let msg = String::from_utf8_lossy(&o.stderr);
867	            let first = msg.lines().find(|l| !l.trim().is_empty()).unwrap_or("unknown error");
868	            format!("Error: {first}")
869	        }
870	    }
871	}
