890	fn visible_width(s: &str) -> usize {
891	    let mut w = 0usize;
892	    let mut chars = s.chars().peekable();
893	    while let Some(c) = chars.next() {
894	        if c == '\x1b' {
895	            for nc in chars.by_ref() { if nc.is_ascii_alphabetic() { break; } }
896	        } else {
897	            w += 1;
898	        }
899	    }
900	    w
901	}
