903	fn relative_time(dt: DateTime<Utc>) -> String {
904	    let secs = (Utc::now() - dt).num_seconds().max(0);
905	    if secs < 604_800 {
906	        match secs {
907	            s if s < 60     => "just now".to_string(),
908	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
909	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
910	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
911	        }
912	    } else {
913	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
914	    }
