fn tui_loop(
    stdout: &mut impl Write,
    sessions: &[DisplaySession],
    local_sessions: &HashSet<String>,
    repos: &[Repository],
) -> Option<Action> {
    let mut sel = 0usize;
    // Fallback when the selected session's cwd doesn't match any tracked repo
    // (e.g. JSONL-only sessions from before init): prefer the repo for the
    // current working directory, so `n`/`s`/`t` still do something useful.
    let cwd_now = env::current_dir().ok().map(|p| p.to_string_lossy().to_string());
    let cwd_repo: Option<&Repository> = cwd_now.as_deref()
        .and_then(|cwd| repos.iter().find(|r| cwd.starts_with(r.directory.as_str())));

    loop {
        let (w, h) = terminal::size().unwrap_or((120, 40));
        let w = w as usize;
        let h = h as usize;

        draw(stdout, sessions, local_sessions, sel, w, h).ok();

        match event::read().ok()? {
            Event::Key(k) => match k.code {
                KeyCode::Char('q') | KeyCode::Esc => break,
                KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
                    execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
                    terminal::disable_raw_mode().ok();
                    std::process::exit(0);
                }
                KeyCode::Up   | KeyCode::Char('k') => { if sel > 0 { sel -= 1; } }
                KeyCode::Down | KeyCode::Char('j') => { if sel + 1 < sessions.len() { sel += 1; } }
                KeyCode::Char('g') => { sel = 0; }
                KeyCode::Char('G') => { sel = sessions.len().saturating_sub(1); }
                KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter => {
                    if sessions.is_empty() { continue; }
                    return Some(Action::Show(sessions[sel].session_id.clone()));
                }
                KeyCode::Char('r') => {
                    if sessions.is_empty() { continue; }
                    let s = &sessions[sel];
                    return Some(Action::Resume(s.session_id.clone(), s.cwd.clone()));
                }
                KeyCode::Char('/') => {
                    if let Some(q) = status::collect_search_query(stdout, w, h) {
                        if !q.trim().is_empty() {
                            // Search prints to the regular stdout, so step
                            // outside the alternate screen and then come back.
                            execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
                            terminal::disable_raw_mode().ok();
                            let _ = super::search::run(&q, 10, false);
                            terminal::enable_raw_mode().ok();
                            execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
                        }
                    }
                    execute!(stdout, terminal::Clear(ClearType::All)).ok();
                }
                KeyCode::Char('n') => {
                    // New worktree against the selected session's repo (or, if
                    // we can't identify one, the cwd's repo).
                    let repo = sessions.get(sel)
                        .and_then(|s| repo_for_session(s, repos, cwd_repo));
                    if let Some(repo) = repo {
                        if let Some(branch) = status::collect_text_input(stdout, "  new worktree branch: ", w, h) {
                            let branch = branch.trim();
                            if !branch.is_empty() {
                                let msg = status::create_worktree(&repo.directory, branch);
                                // Flash the result in the status bar until the
                                // user presses another key (mirrors status.rs).
                                let display: String = msg.chars().take(w).collect();
                                let padded = format!("{:<width$}", display, width = w);
                                execute!(stdout, cursor::MoveTo(0, (h - 1) as u16)).ok();
                                write!(stdout, "\x1b[7m{padded}\x1b[0m").ok();
                                stdout.flush().ok();
                            }
                        }
                    }
                    execute!(stdout, terminal::Clear(ClearType::All)).ok();
                }
                KeyCode::Char('s') => {
                    let repo = sessions.get(sel)
                        .and_then(|s| repo_for_session(s, repos, cwd_repo))
                        .or(cwd_repo);
                    if let Some(repo) = repo {
                        if let Some(cfg) = status::new_session_wizard(stdout, &repo.directory, w, h) {
                            return Some(Action::LaunchNewSession(cfg));
                        }
                    }
                    execute!(stdout, terminal::Clear(ClearType::All)).ok();
                }
                KeyCode::Char('t') => {
                    let repo = sessions.get(sel)
                        .and_then(|s| repo_for_session(s, repos, cwd_repo))
                        .or(cwd_repo);
                    if let Some(repo) = repo {
                        super::tidy::tui_tidy(stdout, std::slice::from_ref(repo), 7, false, w, h);
                    }
                    execute!(stdout, terminal::Clear(ClearType::All)).ok();
                }
                _ => {}
            },
            Event::Resize(_, _) => {
                execute!(stdout, terminal::Clear(ClearType::All)).ok();
            }
            _ => {}
        }
    }

    None
}

