pub fn resolve(&self, cwd: &str, indexing_context: Option<i64>) -> Option<i64> {
    // 1. Longest-prefix cwd match — local, exact, no subprocess.
    let mut best: Option<(usize, i64)> = None;
    if !cwd.is_empty() {
        for (id, dir, _) in &self.repos {
            if cwd.starts_with(dir.as_str()) {
                let n = dir.len();
                if best.map_or(true, |(b, _)| n > b) { best = Some((n, *id)); }
            }
        }
        if let Some((_, id)) = best { return Some(id); }
    }

    // 1b. Same project, different user-home. Strip `/Users/<user>/` (or
    //     `/home/<user>/`) from cwd AND each tracked dir, then prefix-
    //     match the remainders. This catches cross-machine sessions like
    //     Scott's `/Users/sholodak/cosmos/cosmos-graphql` against my own
    //     `/Users/stsoucas/cosmos/cosmos-graphql` without needing the
    //     remote URL lookup (which would require a local clone).
    if let Some(cwd_suffix) = strip_user_home(cwd) {
        let mut best: Option<(usize, i64)> = None;
        for (id, dir, _) in &self.repos {
            if let Some(dir_suffix) = strip_user_home(dir) {
                if path_prefix_match(cwd_suffix, dir_suffix) {
                    let n = dir_suffix.len();
                    if best.map_or(true, |(b, _)| n > b) { best = Some((n, *id)); }
                }
            }
        }
        if let Some((_, id)) = best { return Some(id); }
    }

    // 2. The cwd is local on this machine — ask git for its remote and
    //    match by URL. Stable across machines when both have the repo.
    if !cwd.is_empty() {
        if let Some(remote_url) = self.cached_origin(cwd) {
            if let Some(&id) = self.by_remote.get(&normalize_remote(&remote_url)) {
                return Some(id);
            }
        }
    }

    // 3. Mode B: we're scanning a shared checkpoint repo. Find the project
    //    whose `.entire/settings.json::checkpoint_remote` points at our
    //    current remote.
    if let Some(ctx_id) = indexing_context {
        let ctx_remote = self.repos.iter()
            .find(|(id, _, _)| *id == ctx_id)
            .map(|(_, _, r)| normalize_remote(r));
        if let Some(ctx_remote) = ctx_remote {
            if let Some(candidates) = self.project_for_checkpoint.get(&ctx_remote) {
                if candidates.len() == 1 { return Some(candidates[0]); }
                // Multiple projects share this checkpoint remote — try to
                // disambiguate by matching cwd against project basename
                // (e.g. `/Users/x/cosmos/cosmos-graphql` → cosmos-graphql).
                for &cand in candidates {
                    if let Some((_, dir, _)) = self.repos.iter().find(|(id, _, _)| *id == cand) {
                        if let Some(name) = std::path::Path::new(dir).file_name().and_then(|s| s.to_str()) {
                            if cwd.contains(name) { return Some(cand); }
                        }
                    }
                }
                // Ambiguous and no name match — pick the first; caller can
                // override via reindex once the cwd is local.
                if !candidates.is_empty() { return Some(candidates[0]); }
            }
        }
        // 4. Mode A fallback: scanned repo IS the project repo.
        return Some(ctx_id);
    }

    None
}

